// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ListParties Lista terceros (búsqueda opcional por nombre, paginación keyset).
	// (GET /api/v1/parties/parties)
	ListParties(ctx context.Context, request ListPartiesRequestObject) (ListPartiesResponseObject, error)
	// CreateParty Registra un tercero.
	// (POST /api/v1/parties/parties)
	CreateParty(ctx context.Context, request CreatePartyRequestObject) (CreatePartyResponseObject, error)
	// SearchPartyByDocument Busca por documento exacto (POST para que el número no quede en la URL). Se audita.
	// (POST /api/v1/parties/parties/search-by-document)
	SearchPartyByDocument(ctx context.Context, request SearchPartyByDocumentRequestObject) (SearchPartyByDocumentResponseObject, error)

	// (GET /api/v1/parties/parties/{partyId})
	GetParty(ctx context.Context, request GetPartyRequestObject) (GetPartyResponseObject, error)
	// UpdateParty Rectifica los datos de un tercero (concurrencia optimista por version).
	// (PUT /api/v1/parties/parties/{partyId})
	UpdateParty(ctx context.Context, request UpdatePartyRequestObject) (UpdatePartyResponseObject, error)
	// ListPartyConsents Historial de autorizaciones de tratamiento de datos.
	// (GET /api/v1/parties/parties/{partyId}/consents)
	ListPartyConsents(ctx context.Context, request ListPartyConsentsRequestObject) (ListPartyConsentsResponseObject, error)
	// RegisterPartyConsent Registra una autorización o revocación (Ley 1581/2012). Es inmutable.
	// (POST /api/v1/parties/parties/{partyId}/consents)
	RegisterPartyConsent(ctx context.Context, request RegisterPartyConsentRequestObject) (RegisterPartyConsentResponseObject, error)
	// RevealPartyDocument Devuelve el número de documento completo. Cada lectura queda auditada.
	// (POST /api/v1/parties/parties/{partyId}/document/reveal)
	RevealPartyDocument(ctx context.Context, request RevealPartyDocumentRequestObject) (RevealPartyDocumentResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

